SELECT count(*) from yh_smoke_craving WHERE craving_Time<(SELECT NOW()) AND craving_Time>(select CONCAT(DATE_FORMAT(DATE_SUB(NOW(), INTERVAL 7 DAY),'%Y-%m-%d'),' 00:00:00'))
AND usercode=#{usercode}
GROUP BY DATE_FORMAT(craving_Time,'%Y-%m-%d')

 SELECT count(*) from yh_smoke_craving WHERE craving_Time<(SELECT NOW()) AND craving_Time>(select CONCAT(DATE_FORMAT(DATE_SUB(NOW(), INTERVAL 1 YEAR),'%Y-%m-%d'),' 00:00:00'))
AND usercode=#{usercode}
GROUP BY DATE_FORMAT(craving_Time,'%Y-%m')
